function selectModel(tenant, latencyTargetMs){
  const models = {
    fast: {cost:0.02, latency:80},
    balanced: {cost:0.01, latency:200},
    accurate: {cost:0.04, latency:400}
  };
  const tiers = ['fast','balanced','accurate'].filter(t => models[t].latency <= latencyTargetMs && tenant.budget >= models[t].cost);
  return tiers.length? tiers[0] : 'fast';
}
```

